def bullets(items):
    return [P('&bull;&nbsp; '+x,'Bodyx') for x in items]
def table(rows,widths,header=True):
    data=[]
    for ri,row in enumerate(rows): data.append([P(str(v),'CellHeadx' if header and ri==0 else 'Cellx') for v in row])
    t=Table(data,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    cmds=[('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,HexColor('#D3DED8')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]
    if header: cmds.append(('BACKGROUND',(0,0),(-1,0),navy))
    for i in range(1 if header else 0,len(rows)):
        if i%2==0: cmds.append(('BACKGROUND',(0,i),(-1,i),HexColor('#F4F7F5')))
    t.setStyle(TableStyle(cmds)); story.append(t); story.append(Spacer(1,8))

# Cover
story += [Spacer(1,28*mm), P('MINOR PROJECT REPORT','Centerx'),Spacer(1,9*mm),P('MindGrid','CoverTitle'),P('Interactive Puzzle Arcade and Algorithm Benchmark Suite','CoverSub'),Spacer(1,13*mm)]
# decorative strip
story.append(Table([['','','','']],colWidths=[28*mm]*4,rowHeights=[3*mm],style=TableStyle([('BACKGROUND',(0,0),(0,0),teal),('BACKGROUND',(1,0),(1,0),gold),('BACKGROUND',(2,0),(2,0),navy),('BACKGROUND',(3,0),(3,0),HexColor('#9DB7AA'))])))
story += [Spacer(1,12*mm),P('Submitted in partial fulfillment of the requirements for the degree of','Centerx'),P('Master of Computer Applications (MCA)','Centerx'),Spacer(1,8*mm),P('Submitted to','Centerx'),P('Chandigarh University<br/>Gharuan, Mohali, Punjab','Centerx'),Spacer(1,8*mm),P('Submitted by','Centerx'),P('<b>Nitin Kumar</b><br/>UID: 26MCA20235','Centerx'),Spacer(1,8*mm),P('Project Guide: ______________________________','Centerx'),Spacer(1,12*mm),P('1 November 2026','Centerx'),PageBreak()]

story += [P('Certificate of Originality','H1x'),Spacer(1,8*mm),P('This is to certify that the project report entitled <b>“MindGrid: Interactive Puzzle Arcade and Algorithm Benchmark Suite”</b>, submitted by <b>Nitin Kumar (UID: 26MCA20235)</b> in partial fulfillment of the requirements for the award of the degree of Master of Computer Applications at Chandigarh University, is a record of project work completed by the student.', 'Bodyx'),Spacer(1,5*mm),P('The work presented in this report has not been submitted, in whole or in part, to any other university or institute for the award of a degree or diploma.', 'Bodyx'),Spacer(1,23*mm),table([['Date','Project Guide','Student'],['1 November 2026','________________________','Nitin Kumar']], [48*mm,67*mm,48*mm],False),Spacer(1,17*mm),P('Acknowledgement','H1x'),P('I express my sincere gratitude to my project guide and the faculty of Chandigarh University for their guidance and support during the development of MindGrid. I also thank my family and peers for their encouragement. The project provided an opportunity to apply programming fundamentals, algorithm design, and interface development to an interactive software product.','Bodyx'),Spacer(1,12*mm),P('<b>Nitin Kumar</b><br/>UID: 26MCA20235','Bodyx'),PageBreak()]

story += [P('Abstract','H1x'),P('MindGrid is an interactive puzzle arcade that brings four familiar games together with algorithmic solvers and a compact benchmark dashboard. The browser edition is built with semantic HTML, responsive CSS, and plain JavaScript, with no framework, build step, or package installation required. A companion C++17 console program implements the same game themes and stores a small player profile locally.', 'Bodyx'),P('The arcade includes Sudoku, Connect Four, N-Queens, and 2048. Its algorithms demonstrate constraint-based Sudoku solving with bit masks and a minimum-remaining-values choice, minimax search with alpha-beta pruning for Connect Four, bitwise backtracking for N-Queens, and a heuristic move evaluation for 2048. The browser interface provides game navigation, responsive boards, keyboard controls where relevant, undo or reset controls, and browser-local progress. The C++ program provides interactive play, solver runs, and timing output.', 'Bodyx'),P('This report describes the project goals, requirements, architecture, game state models, algorithm choices, interface, persistence, and possible extensions. It reflects the implementation present in the accompanying source code. The browser build is a client-side application; it does not currently depend on a Node.js or Express backend, user authentication, or a remote leaderboard.', 'Bodyx'),P('Keywords: puzzle arcade, JavaScript, C++17, backtracking, minimax, alpha-beta pruning, heuristic search','Smallx'),PageBreak()]

story += [P('Contents','H1x')]
contents=[('Abstract','i'),('1. Introduction','1'),('2. Requirements and Scope','2'),('3. System Architecture and Technology','3'),('4. Game Modules and Algorithms','4'),('5. Interface, Persistence and Benchmarking','6'),('6. Implementation and Operation','7'),('7. Conclusion and Future Scope','8'),('References','9')]
table([['Section','Page']]+[[a,b] for a,b in contents],[130*mm,25*mm])
story += [Spacer(1,6*mm),P('Project at a glance','H2x'),table([['Attribute','Description'],['Project name','MindGrid'],['Deliverables','Browser arcade (web/) and C++17 console application (main.cpp)'],['Primary users','Learners and players interested in puzzles and algorithm demonstrations'],['Core modules','Sudoku, Connect Four, N-Queens, 2048, player profile, solver benchmarks'],['Browser setup','Open web/index.html in a modern browser; no install step']], [42*mm,113*mm]),PageBreak()]

story += [P('1. Introduction','H1x'),P('1.1 Project overview','H2x'),P('MindGrid is a small game and learning environment organized around four puzzle types. Each module pairs an interactive play mode with an algorithmic solver or move suggestion. A shared navigation shell lets the player move between games, review a profile summary, and run benchmark tasks. The codebase offers two implementations: a web interface designed for direct browser use and a terminal-based C++17 application.', 'Bodyx'),P('1.2 Problem statement','H2x'),P('Puzzle examples are often isolated exercises: they demonstrate a single algorithm but provide little context for interaction, progress, or comparison. MindGrid addresses this by presenting several distinct search problems through one arcade, making their state representations and solution strategies accessible through play and timing output.', 'Bodyx'),P('1.3 Objectives','H2x'),*bullets(['Combine four puzzle experiences behind a consistent menu and visual identity.','Demonstrate different algorithmic approaches on concrete game states.','Provide input validation, reset or undo controls, and useful progress feedback.','Measure solver execution locally and show useful search statistics where available.','Keep the web version simple to run, with no framework or build pipeline.']),P('1.4 Scope and assumptions','H2x'),P('The current system runs locally in a browser or terminal. Browser profile data is stored in localStorage; the console profile is stored in profile.txt. Benchmark measurements are machine- and runtime-dependent and should be treated as observations for a particular run, not fixed performance claims. No server-side account, shared database, or network service is part of the present implementation.', 'Bodyx'),PageBreak()]

story += [P('2. Requirements and Scope','H1x'),P('2.1 Functional requirements','H2x'),table([['ID','Requirement','Implementation'],['FR-01','Navigate among overview, games, and benchmark screens.','Browser navigation controls and console menu.'],['FR-02','Play Sudoku with valid placements and solve a generated puzzle.','Constraint checks, puzzle generator, backtracking solver.'],['FR-03','Play Connect Four against a computer opponent.','Human-versus-AI board; minimax with alpha-beta pruning.'],['FR-04','Place queens safely and enumerate N-Queens solutions.','Interactive row-based placement; bitwise backtracking search.'],['FR-05','Play 2048, undo, request a suggested move, or use autoplay.','Matrix moves, history snapshots, one-ply heuristic selection.'],['FR-06','Track local progress and run solver benchmarks.','Browser localStorage and C++ profile.txt; elapsed-time metrics.']],[14*mm,64*mm,77*mm]),P('2.2 Quality goals','H2x'),*bullets(['Usability: clear controls, visible game status, and responsive page layout.','Correctness: enforce game rules and preserve valid state transitions.','Maintainability: keep each game engine and rendering path identifiable within the source.','Portability: use standard browser APIs in the web build and standard C++17 facilities in the console build.']),P('2.3 Constraints','H2x'),P('The browser benchmark suite runs on the user’s device and has no cross-device normalization. Browser storage is local to the profile and may be cleared by the browser. Console profile saving relies on write access to the program’s working directory. The browser app is delivered as static files and currently has no server component.', 'Bodyx'),PageBreak()]

story += [P('3. System Architecture and Technology','H1x'),P('3.1 Technology stack','H2x'),table([['Technology','Role'],['HTML5','Semantic document shell, navigation regions, and application containers.'],['CSS3','Responsive layout, visual theme, game boards, and interaction states.'],['Vanilla JavaScript','Browser routing, game state, rendering, puzzle rules, solvers, local storage, and timers.'],['C++17','Standalone console implementation of the four games, profile, and solver timing.'],['Browser localStorage / profile.txt','Local persistence for browser and console profile summaries respectively.']],[46*mm,109*mm]),P('3.2 Component organization','H2x'),P('The web application is organized into three files: index.html defines the shell and navigation; styles.css controls layout and presentation; app.js contains the game engines, UI rendering, event handling, and local profile logic. The root main.cpp contains the console application, including utility functions, a shared Game interface, profile handling, game classes, and the main menu. The web/README.md documents how to launch the browser version and run its engine checks.', 'Bodyx'),P('3.3 Browser data flow','H2x'),table([['Stage','Action'],['1. Load','Browser loads index.html, styles.css, and app.js from the local project folder.'],['2. Initialize','JavaScript reads the local profile safely and renders the overview.'],['3. Interact','User actions are dispatched to game-specific handlers that update state.'],['4. Render','The active view is redrawn from the current state and status values.'],['5. Persist','Progress summaries are serialized to localStorage after relevant events.']],[30*mm,125*mm]),P('3.4 Console data flow','H2x'),P('The C++ main function loads profile.txt, constructs the game modules, and displays a menu. A selected game can be played, reset, or benchmarked. Solver timing uses a steady clock and reports elapsed microseconds or milliseconds together with algorithm-specific statistics where implemented. The profile is written back to the local file when tracked results change.', 'Bodyx'),PageBreak()]

story += [P('4. Game Modules and Algorithms','H1x'),P('4.1 Sudoku','H2x'),P('The 9×9 Sudoku module represents rows, columns, and 3×3 boxes as bit masks. Candidate values are derived from masks. The solver selects an empty cell with the fewest legal candidates (minimum remaining values), then recursively tries candidates and backtracks on conflict. Puzzle generation starts from a completed grid, removes entries in randomized order, and checks that the remaining puzzle has a unique solution. In the browser, difficulty affects the number of removed clues; the console generator targets a fixed clue-removal count.', 'Bodyx'),P('4.2 Connect Four','H2x'),P('Connect Four uses a 6×7 board. The computer evaluates future moves with minimax and alpha-beta pruning. A board evaluation scores groups of four, favors the center, rewards the AI’s potential lines, and penalizes human threats. Search statistics include visited nodes and pruning cutoffs in the interface or console output. The browser opponent uses a bounded look-ahead and reports the most recent search activity.', 'Bodyx'),P('4.3 N-Queens','H2x'),P('The N-Queens module asks the player to place one queen per row without sharing columns or diagonals. The solver uses bit masks for occupied columns and diagonal attacks, then recursively visits available positions. It can find a placement or count valid arrangements. The browser exposes board sizes from 4 through 14; the console allows interactive board sizes from 4 through 14.', 'Bodyx'),P('4.4 2048','H2x'),P('The 2048 module shifts a 4×4 matrix and merges equal adjacent tiles, with each resulting tile allowed to merge only once per move. New tiles are spawned in empty cells. Undo uses saved state snapshots. The hint/autoplay helper evaluates the immediate result of each legal direction using a heuristic that considers open cells, neighboring tile order, the largest tile, corner placement, and points earned. This is a greedy one-step policy rather than a full expectimax search.', 'Bodyx'),PageBreak()]

story += [P('5. Interface, Persistence and Benchmarking','H1x'),P('5.1 Browser interface','H2x'),P('The web interface uses a dark green arcade theme, a persistent side navigation, a top status bar, and a central view that changes with the selected screen. Game-specific boards are rendered from JavaScript state. Layout rules in CSS adapt the arcade for narrower screens. The home view summarizes progress and links to the games; the benchmark screen introduces the solver suite and displays results after a run.', 'Bodyx'),P('5.2 Controls and feedback','H2x'),table([['Module','Controls and feedback'],['Sudoku','Select a cell and enter a value; invalid conflicts are reported. Generate a new puzzle or invoke the solver.'],['Connect Four','Select a column to drop a disc; the opponent responds after its search. Win, draw, and AI activity are shown.'],['N-Queens','Select a safe square in the next row; undo or clear placements. Find a solution or count all arrangements.'],['2048','Use W/A/S/D or arrow keys; request a hint, autoplay, undo, or start a new board. Score and game-over state are visible.']],[34*mm,121*mm]),P('5.3 Persistence and profile','H2x'),P('The browser saves a small profile object under the key mindgrid-profile-v1. It includes solved count, 2048 high score, and fastest solver time. The C++ profile stores games solved, 2048 high score, and fastest solver duration in profile.txt. These are local persistence mechanisms: data does not synchronize across devices or users.', 'Bodyx'),P('5.4 Benchmark design','H2x'),P('The browser suite measures a Sudoku solve, a Connect Four move search, an N-Queens search, and a 2048 best-move scan. Timings are shown in milliseconds, with supporting output such as solution counts, nodes, cutoffs, or suggested moves. The console suite runs each game’s solver benchmark and reports elapsed time. Since puzzle state, hardware, browser, compiler, and system load vary, the report intentionally includes no fabricated benchmark numbers.', 'Bodyx'),PageBreak()]

story += [P('6. Implementation and Operation','H1x'),P('6.1 Project files','H2x'),table([['Path','Purpose'],['main.cpp','C++17 console arcade and solver implementations.'],['web/index.html','Browser application shell and navigation.'],['web/styles.css','Responsive visual design and board styles.'],['web/app.js','Browser game logic, UI rendering, solver suite, and profile.'],['web/README.md','Run instructions and project file overview.'],['web/tests/engines.test.cjs','Node-based logic checks for browser engines.']],[63*mm,92*mm]),P('6.2 Running the browser edition','H2x'),P('Open web/index.html in a modern browser. The project has no framework, package installation, or build step. Local storage must be enabled for profile persistence.', 'Bodyx'),P('6.3 Building the console edition','H2x'),P('With a C++17 compiler available, compile main.cpp using a command such as:','Bodyx'),table([['Example build command'],['g++ -std=c++17 -O2 -Wall -Wextra -pedantic main.cpp -o mindgrid']],[155*mm],False),P('Run the resulting executable from a writable working directory if profile persistence is desired. The application presents a menu for Sudoku, Connect Four, N-Queens, 2048, player profile, and the benchmark suite.', 'Bodyx'),P('6.4 Verification approach','H2x'),P('The repository includes web/tests/engines.test.cjs and documents the command node --test .\\web\\tests\\engines.test.cjs. The tests cover browser game engines. Additional manual review should cover responsive rendering, keyboard and pointer interaction, profile persistence, solver completion, and boundary cases such as full columns or completed boards.', 'Bodyx'),PageBreak()]

story += [P('7. Conclusion and Future Scope','H1x'),P('7.1 Conclusion','H2x'),P('MindGrid combines four puzzle experiences with algorithm demonstrations in both a static browser application and a C++17 console program. The project brings together interactive state management, constraint solving, game-tree search, bitwise recursion, local profile storage, and benchmark reporting. Its lightweight browser implementation can be opened directly, while the console version offers a second environment for exploring the same themes.', 'Bodyx'),P('The design makes the algorithms concrete: players can use solvers and hints, inspect search activity, and compare locally measured runs. The current implementation remains self-contained and stores progress locally, which suits a learning project and leaves clear extension points for broader deployment.', 'Bodyx'),P('7.2 Future scope','H2x'),*bullets(['Add optional online accounts and a secure backend for cross-device profile synchronization.','Store benchmark history and provide repeatable run comparisons with environment metadata.','Add accessibility improvements such as fuller keyboard navigation, screen-reader announcements, and configurable contrast.','Extend Sudoku difficulty controls and add validation for saved or imported puzzle states.','Explore deeper 2048 search with chance-node evaluation and compare it against the current greedy heuristic.','Add multiplayer or local two-player options and expanded puzzle variants.']),P('References','H1x'),*bullets(['Project source code: main.cpp, web/app.js, web/index.html, and web/styles.css.','Project run instructions: web/README.md.','C++ language reference: ISO C++17 standard library facilities used by the implementation.','MDN Web Docs: HTML, CSS, JavaScript, and Window.localStorage documentation.']),Spacer(1,5*mm),P('--- End of Report ---','Centerx')]


def footer(canvas,doc):
    canvas.saveState(); w,h=A4
    if doc.page>1:
        canvas.setStrokeColor(HexColor('#D8E2DC')); canvas.line(25*mm,16*mm,w-25*mm,16*mm)
        canvas.setFont('Helvetica',8); canvas.setFillColor(muted)
        canvas.drawString(25*mm,10.5*mm,'MindGrid | Nitin Kumar | 26MCA20235')
        label = ['i','ii','iii'][doc.page-2] if 2 <= doc.page <= 4 else str(doc.page-4)
        canvas.drawRightString(w-25*mm,10.5*mm,label)
    canvas.restoreState()

doc=SimpleDocTemplate(OUT,pagesize=A4,rightMargin=25*mm,leftMargin=25*mm,topMargin=23*mm,bottomMargin=23*mm,title='MindGrid Project Report',author='Nitin Kumar',subject='MCA Minor Project Report')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT)

